1: import { Injectable } from '@angular/core';
2: import { HttpClient, HttpHeaders } from '@angular/common/http';
3: import { environment } from '../../environments/environment';
4: import { catchError, map } from 'rxjs/operators';
5: import { HttpErrorManager } from './errorManager'
6: 
7: /**
8:  * This class manage the http connections with internal REST services. Use the response format {
9:  *  Code: 'xxxxx',
10:  *  Body: 'Some Data' (this element is returned if the request is success)
11:  *  ...
12:  * }
13:  */
14: @Injectable({
15:   providedIn: 'root',
16: })
17: export class RequestManager {
18:   private path!: any;
19:   constructor(private http: HttpClient, private errManager: HttpErrorManager) {}
20: 
21:   private getHttpOptions(): any {
22:     const acces_token = window.localStorage.getItem('access_token');
23:     let headers = new HttpHeaders({
24:       'Content-Type': 'application/json',
25:     });
26:     if (acces_token !== null) {
27:       headers = headers.set('Authorization', `Bearer ${acces_token}`);
28:     }
29:     return { headers };
30:   }
31: 
32: 
33:   /**
34:    * Use for set the source path of the service (service's name must be present at src/environment/environment.ts)
35:    * @param service: string
36:    */
37:   public setPath(service: string) {
38:     this.path = environment[service as keyof typeof environment];
39:   }
40: 
41: 
42:   /**
43:    * Perform a GET http request
44:    * @param endpoint service's end-point
45:    * @param params (an Key, Value object with que query params for the request)
46:    * @returns Observable<any>
47:    */
48:   get(endpoint: any) {
49:     return this.http.get<any>(`${this.path}${endpoint}`, this.getHttpOptions()).pipe(
50:       map(
51:         (res) => {
52:           if (res?.hasOwnProperty('Body')) {
53:             return res;
54:           } else {
55:             return res;
56:           }
57:         },
58:       ),
59:       catchError(this.errManager.handleError.bind(this)),
60:     );
61:   }
62: 
63:   /**
64:    * Perform a POST http request
65:    * @param endpoint service's end-point
66:    * @param element data to send as JSON
67:    * @returns Observable<any>
68:    */
69:   post(endpoint: any, element: any) {
70:     return this.http.post<any>(`${this.path}${endpoint}`, element, this.getHttpOptions()).pipe(
71:       catchError(this.errManager.handleError),
72:     );
73:   }
74: 
75:   /**
76:    * Perform a POST http request
77:    * @param endpoint service's end-point
78:    * @param element data to send as JSON
79:    * @returns Observable<any>
80:    */
81:   post_file(endpoint: any, element: any) {
82:     const acces_token = window.localStorage.getItem('access_token');
83:     let headers = new HttpHeaders({
84:       'Content-Type': 'multipart/form-data',
85:     });
86:     if (acces_token !== null) {
87:       headers = headers.set('Authorization', `Bearer ${acces_token}`);
88:     }
89:     return this.http.post<any>(`${this.path}${endpoint}`, element, { headers }).pipe(
90:       catchError(this.errManager.handleError),
91:     );
92:   }
93: 
94:   /**
95:    * Perform a PUT http request
96:    * @param endpoint service's end-point
97:    * @param element data to send as JSON, With the id to UPDATE
98:    * @returns Observable<any>
99:    */
100:   put(endpoint: any, element: { Id: any; }) {
101:     const endpointPath = String(endpoint).replace(/\/$/, '');
102:     const elementId = element?.Id;
103:     const path = (elementId && !endpointPath.endsWith(`/${elementId}`)) ? `${this.path}${endpointPath}/${elementId}` : `${this.path}${endpointPath}`;
104:     return this.http.put<any>(path, element, this.getHttpOptions()).pipe(
105:       catchError(this.errManager.handleError),
106:     );
107:   }
108: 
109:   /**
110:    * Perform a DELETE http request
111:    * @param endpoint service's end-point
112:    * @param id element's id for remove
113:    * @returns Observable<any>
114:    */
115:   delete(endpoint: any, id: any, element?: any) {
116:     const options = { ...this.getHttpOptions(), body: element };
117:     return this.http.delete<any>(`${this.path}${endpoint}/${id}`, options).pipe(
118:       catchError(this.errManager.handleError),
119:     );
120:   }
121: };

